// =============================================================================
// L14 [C++20]  capstone: everything together
// =============================================================================
// Part 1  CRC-32: a 256-entry lookup table generated by the compiler, and a
//         checksum function that works at compile time and at runtime
// Part 2  A command dispatcher: switch on strings with consteval ids, and a
//         compile-time check that no two commands collide
// Part 3  The 88 piano keys: names, MIDI numbers and frequencies computed at
//         compile time, with consteval lookups that reject bad input
//
// Features used: constexpr functions with loops (C++14), constexpr lambdas
// and std::array/string_view (C++17), consteval and class-type checks (C++20).
// =============================================================================
#pragma once

#include "../Lesson.h"

#if TUTORIAL_INCLUDE(20)

#include <array>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <string>
#include <string_view>

namespace l14_capstone {

const int STD = 20;

// =============================================================================
// Part 1: CRC-32
// =============================================================================
constexpr std::array<std::uint32_t, 256> make_crc_table()
{
    std::array<std::uint32_t, 256> table{};
    for (std::uint32_t i = 0; i < 256; ++i) {
        std::uint32_t c = i;
        for (int bit = 0; bit < 8; ++bit)
            c = (c & 1u) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
        table[i] = c;
    }
    return table;
}

inline constexpr auto kCrcTable = make_crc_table();   // computed once, by the compiler
static_assert(kCrcTable[1] == 0x77073096u);

constexpr std::uint32_t crc32(std::string_view data)
{
    std::uint32_t crc = 0xFFFFFFFFu;
    for (char ch : data)
        crc = kCrcTable[(crc ^ static_cast<unsigned char>(ch)) & 0xFFu] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFFu;
}

// The standard check value for CRC-32: if this compiles, the table is right.
static_assert(crc32("123456789") == 0xCBF43926u);

// =============================================================================
// Part 2: command dispatcher
// =============================================================================
consteval std::uint32_t operator""_id(const char* s, std::size_t n) { return crc32({s, n}); }

struct Command {
    std::string_view name;
    std::string_view help;
};

inline constexpr std::array kCommands{
    Command{"play", "start playback"},
    Command{"stop", "stop playback"},
    Command{"tempo", "set the tempo"},
    Command{"transpose", "shift all notes"},
};

// Two different names could, in theory, give the same CRC. Check at compile time.
template <std::size_t N>
consteval bool ids_unique(const std::array<Command, N>& commands)
{
    for (std::size_t i = 0; i < N; ++i)
        for (std::size_t j = i + 1; j < N; ++j)
            if (crc32(commands[i].name) == crc32(commands[j].name))
                return false;
    return true;
}
static_assert(ids_unique(kCommands), "two commands have the same id");

// ERROR DEMO [L14-E1]  fails in: every standard
// A command table with a duplicate entry fails the compile-time check.
#if TUTORIAL_FORCE_ERRORS
inline constexpr std::array kBadCommands{Command{"play", "a"}, Command{"stop", "b"}, Command{"play", "c"}};
static_assert(ids_unique(kBadCommands), "two commands have the same id");
#endif

inline std::string_view dispatch(std::string_view input)   // input arrives at runtime
{
    switch (crc32(input)) {
    case "play"_id:      return kCommands[0].help;
    case "stop"_id:      return kCommands[1].help;
    case "tempo"_id:     return kCommands[2].help;
    case "transpose"_id: return kCommands[3].help;
    default:             return "unknown command";
    }
}

// =============================================================================
// Part 3: the 88 piano keys
// =============================================================================
// Key 1 is A0 (27.5 Hz), key 49 is A4 (440 Hz), key 88 is C8.
// Equal temperament: every semitone multiplies the frequency by 2^(1/12).
struct PianoKey {
    int number;       // 1..88
    int midi;         // 21..108
    char name[4];     // "A0", "C#4", ...
    double frequency; // Hz
};

// 2^(1/12) by Newton's method: solve r^12 = 2. (std::pow isn't constexpr.)
consteval double semitone_ratio()
{
    double r = 1.06;
    for (int i = 0; i < 20; ++i) {
        double r11 = 1.0;
        for (int k = 0; k < 11; ++k)
            r11 *= r;
        r = r - (r11 * r - 2.0) / (12.0 * r11);
    }
    return r;
}
inline constexpr double kSemitone = semitone_ratio();

constexpr std::array<PianoKey, 88> make_keyboard()
{
    constexpr const char* kNames[] = {"A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"};
    std::array<PianoKey, 88> keys{};
    for (int i = 0; i < 88; ++i) {
        PianoKey& k = keys[i];
        k.number = i + 1;
        k.midi = i + 21;

        // Name: letter(s) + octave. Octave numbers change at C, not at A.
        const char* letter = kNames[i % 12];
        const int octave = (i + 9) / 12;
        int pos = 0;
        while (*letter)
            k.name[pos++] = *letter++;
        k.name[pos++] = static_cast<char>('0' + octave);
        k.name[pos] = '\0';

        // Frequency: 27.5 * 2^(i/12) * r^(i%12) - exact octaves, small error.
        double f = 27.5;
        for (int o = 0; o < i / 12; ++o)
            f *= 2.0;
        for (int s = 0; s < i % 12; ++s)
            f *= kSemitone;
        k.frequency = f;
    }
    return keys;
}

inline constexpr auto kKeyboard = make_keyboard();

constexpr bool nearly(double a, double b) { return (a > b ? a - b : b - a) < 1e-9; }
static_assert(kKeyboard[48].frequency == 440.0);              // A4 exactly
static_assert(nearly(kKeyboard[39].frequency, 261.6255653005986));   // C4, middle C
static_assert(kKeyboard[87].midi == 108);

// consteval lookups: a wrong key number or name is a COMPILE error.
consteval const PianoKey& key(int number)
{
    if (number < 1 || number > 88)
        throw "piano keys are numbered 1..88";
    return kKeyboard[number - 1];
}

consteval int key_number(std::string_view name)
{
    for (const PianoKey& k : kKeyboard)
        if (name == k.name)
            return k.number;
    throw "unknown note name";
}

static_assert(key(49).midi == 69);
static_assert(key_number("C4") == 40);
static_assert(key(key_number("A0")).frequency == 27.5);

// ERROR DEMO [L14-E2]  fails in: every standard
// There is no key 89.
#if TUTORIAL_FORCE_ERRORS
inline constexpr double kNoSuchKey = key(89).frequency;
#endif

// ERROR DEMO [L14-E3]  fails in: every standard
// "H4" is the German name for B4 - not in our table.
#if TUTORIAL_FORCE_ERRORS
inline constexpr int kGermanB = key_number("H4");
#endif

// -----------------------------------------------------------------------------
// run()
// -----------------------------------------------------------------------------
inline std::string hex(std::uint32_t v)
{
    char buf[11];
    std::snprintf(buf, sizeof buf, "0x%08X", static_cast<unsigned>(v));
    return buf;
}

inline void run()
{
    tut::header(STD, "L14", "capstone: CRC-32, string commands, piano keys");

    tut::section(STD, "Part 1: CRC-32 (table built by the compiler)");
    tut::show(STD, "kCrcTable[1]", hex(kCrcTable[1]));
    tut::show(STD, "crc32(\"123456789\")", hex(crc32("123456789")));
    std::string runtimeText = "constexpr";
    runtimeText += " at runtime";
    tut::show(STD, "crc32(runtime string)", hex(crc32(runtimeText)));

    tut::section(STD, "Part 2: dispatching commands");
    for (std::string_view cmd : {"play", "transpose", "loop"})
        tut::show(STD, "dispatch(\"" + std::string(cmd) + "\")", dispatch(cmd));

    tut::section(STD, "Part 3: piano keys (every A, plus middle C and C8)");
    constexpr int kShown[] = {1, 13, 25, 37, 40, 49, 61, 73, 85, 88};
    for (int n : kShown) {
        const PianoKey& k = kKeyboard[n - 1];
        char line[64];
        std::snprintf(line, sizeof line, "MIDI %3d  %9.3f Hz", k.midi, k.frequency);
        tut::show(STD, "key " + std::to_string(k.number) + "  " + k.name, line);
    }
    tut::show(STD, "key(key_number(\"C4\")).frequency", key(key_number("C4")).frequency);
}

} // namespace l14_capstone

#endif // TUTORIAL_INCLUDE(20)
